// План specs/payments-portal.md 3.1 / 3.2 (#ec42a8). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Refund НЕ подтверждается: окно и Cancel.
// 3.1 — Refund открывает окно ПРИЛОЖЕНИЯ (role=dialog), не системный confirm браузера: «Refund this payment?», сумма и клиент,
//        «A refund cannot be undone.», кнопки Cancel / Refund. 3.2 — Cancel закрывает окно, ничего не меняется.
// Источник: «מה רצוי» — подтверждение в окне системы с суммой и клиентом, кнопки Refund / Cancel. Факты 17.11 (app + web): окно
// «$1 goes back to TTP Customer's card.», системный dialog = 0. Без пометки устройства — десктоп + телефоны (окно читается).
import { test, expect } from '../../fixtures';
import { ROLE, kpi, openPortal, txRows } from './portal-helpers';

/** Строки с кнопкой Refund (у Refunded-платежей кнопки нет). */
const refundable = (page: import('@playwright/test').Page) =>
  txRows(page).filter({ has: page.getByRole('button', { name: 'Refund', exact: true }) });

test.describe('Payment Portal — Refund confirmation window (#ec42a8)', () => {
  test('Refund opens an app window with amount and customer, a no-undo warning and Cancel / Refund — no browser confirm #ec42a8', async ({ asUser }) => {
    const page = await asUser(ROLE);
    let systemDialogs = 0;
    page.on('dialog', async (d) => { systemDialogs++; await d.dismiss(); });
    await openPortal(page);

    const row = refundable(page).first();
    await expect(row, 'есть платёж, который можно вернуть (Succeeded, 4242)').toBeVisible();
    await row.getByRole('button', { name: 'Refund', exact: true }).click();

    const dialog = page.getByRole('dialog').or(page.getByRole('alertdialog')).filter({ hasText: 'Refund this payment?' });
    await expect(dialog).toBeVisible();
    await expect(dialog).toContainText(/\$\d[\d,.]* goes back to .+'s card\./);
    await expect(dialog).toContainText('TTP Customer');
    await expect(dialog).toContainText('A refund cannot be undone.');
    await expect(dialog.getByRole('button', { name: 'Cancel', exact: true })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'Refund', exact: true })).toBeVisible();
    expect(systemDialogs, 'системного окна браузера (confirm/alert) нет').toBe(0);

    await dialog.getByRole('button', { name: 'Cancel', exact: true }).click();
    await expect(dialog).toBeHidden();
  });

  test('Cancel in the Refund window changes nothing: no toast, same totals, same number of Refunded rows #ec42a8', async ({ asUser }) => {
    const page = await asUser(ROLE);
    let systemDialogs = 0;
    page.on('dialog', async (d) => { systemDialogs++; await d.dismiss(); });
    await openPortal(page);

    const totalBefore = await kpi(page, 'Total Transactions');
    const refundedBefore = await txRows(page).filter({ hasText: 'Refunded' }).count();

    await refundable(page).first().getByRole('button', { name: 'Refund', exact: true }).click();
    const dialog = page.getByRole('dialog').or(page.getByRole('alertdialog')).filter({ hasText: 'Refund this payment?' });
    await expect(dialog).toBeVisible();
    await dialog.getByRole('button', { name: 'Cancel', exact: true }).click();
    await expect(dialog).toBeHidden();

    await expect(page.getByText('The payment was refunded.')).toHaveCount(0);
    expect(await kpi(page, 'Total Transactions'), 'Total Transactions не изменился').toBe(totalBefore);
    await expect(txRows(page).filter({ hasText: 'Refunded' }), 'число Refunded-строк не изменилось').toHaveCount(refundedBefore);
    expect(systemDialogs).toBe(0);
  });
});
